spec.expr:
sum(
  up{
    departamento=~"$departamento",
    nodename=~"$nodename"
  } == 1
)

node_load1{
  departamento=~"$departamento",
  nodename=~"$nodename"
}

sum by (nodename) (
  rate(
    node_network_receive_bytes_total{
      departamento=~"$departamento",
      nodename=~"$nodename",
      device!~"lo|docker.*|veth.*|br-.*"
    }[5m]
  )
)

sum by (nodename) (
  rate(
    node_network_transmit_bytes_total{
      departamento=~"$departamento",
      nodename=~"$nodename",
      device!~"lo|docker.*|veth.*|br-.*"
    }[5m]
  )
)

sum by (nodename) (
  rate(
    node_disk_read_bytes_total{
      departamento=~"$departamento",
      nodename=~"$nodename",
      device!~"loop.*|ram.*|fd.*|sr.*"
    }[5m]
  )
)

sum by (nodename) (
  rate(
    node_disk_written_bytes_total{
      departamento=~"$departamento",
      nodename=~"$nodename",
      device!~"loop.*|ram.*|fd.*|sr.*"
    }[5m]
  )
)

sum by (nodename) (
  rate(
    node_network_receive_errs_total{
      departamento=~"$departamento",
      nodename=~"$nodename",
      device!~"lo|docker.*|veth.*|br-.*"
    }[5m]
  )
)

sum by (nodename) (
  rate(
    node_network_transmit_errs_total{
      departamento=~"$departamento",
      nodename=~"$nodename",
      device!~"lo|docker.*|veth.*|br-.*"
    }[5m]
  )
)

sum by (nodename) (
  rate(
    node_network_receive_drop_total{
      departamento=~"$departamento",
      nodename=~"$nodename",
      device!~"lo|docker.*|veth.*|br-.*"
    }[5m]
  )
)

sum by (nodename) (
  rate(
    node_network_transmit_drop_total{
      departamento=~"$departamento",
      nodename=~"$nodename",
      device!~"lo|docker.*|veth.*|br-.*"
    }[5m]
  )
)

(
  time()
  -
  node_boot_time_seconds{
    departamento=~"$departamento",
    nodename=~"$nodename"
  }
) / 86400

node_procs_running{
  departamento=~"$departamento",
  nodename=~"$nodename"
}

node_procs_blocked{
  departamento=~"$departamento",
  nodename=~"$nodename"
}

100 *
(
  node_memory_SwapTotal_bytes{
    departamento=~"$departamento",
    nodename=~"$nodename"
  }
  -
  node_memory_SwapFree_bytes{
    departamento=~"$departamento",
    nodename=~"$nodename"
  }
)
/
clamp_min(
  node_memory_SwapTotal_bytes{
    departamento=~"$departamento",
    nodename=~"$nodename"
  },
  1
)

avg by (nodename) (
  rate(
    node_cpu_seconds_total{
      mode="iowait",
      departamento=~"$departamento",
      nodename=~"$nodename"
    }[5m]
  )
) * 100

node_memory_MemAvailable_bytes{
  departamento=~"$departamento",
  nodename=~"$nodename"
}

sum(
  up{
    departamento=~"$departamento",
    nodename=~"$nodename"
  } == bool 0
)

100 * (
  1 -
  (
    node_filesystem_files_free{
      departamento=~"$departamento",
      nodename=~"$nodename",
      fstype!~"tmpfs|overlay|squashfs|ramfs|rootfs",
      mountpoint!~"/run.*|/snap.*|/var/lib/docker.*"
    }
    /
    node_filesystem_files{
      departamento=~"$departamento",
      nodename=~"$nodename",
      fstype!~"tmpfs|overlay|squashfs|ramfs|rootfs",
      mountpoint!~"/run.*|/snap.*|/var/lib/docker.*"
    }
  )
)

100 *
(
  node_filefd_allocated{
    departamento=~"$departamento",
    nodename=~"$nodename"
  }
  /
  node_filefd_maximum{
    departamento=~"$departamento",
    nodename=~"$nodename"
  }
)

sum by (nodename) (
  rate(
    node_context_switches_total{
      departamento=~"$departamento",
      nodename=~"$nodename"
    }[5m]
  )
)

100 *
node_load1{
  departamento=~"$departamento",
  nodename=~"$nodename"
}
/
on(nodename)
count by(nodename) (
  node_cpu_seconds_total{
    mode="idle",
    departamento=~"$departamento",
    nodename=~"$nodename"
  }
)

label_replace(
  max by (departamento, nodename) (
    up{
      departamento=~"$departamento",
      nodename=~"$nodename"
    }
  ),
  "metric", "Estado", "nodename", ".*"
)

label_replace(
  100 - (
    avg by (departamento, nodename) (
      rate(
        node_cpu_seconds_total{
          mode="idle",
          departamento=~"$departamento",
          nodename=~"$nodename"
        }[5m]
      )
    ) * 100
  ),
  "metric", "CPU %", "nodename", ".*"
)

label_replace(
  avg by (departamento, nodename) (
    100 * (
      1 -
      (
        node_memory_MemAvailable_bytes{
          departamento=~"$departamento",
          nodename=~"$nodename"
        }
        /
        node_memory_MemTotal_bytes{
          departamento=~"$departamento",
          nodename=~"$nodename"
        }
      )
    )
  ),
  "metric", "RAM %", "nodename", ".*"
)

label_replace(
  max by (departamento, nodename) (
    100 * (
      1 -
      (
        node_filesystem_avail_bytes{
          departamento=~"$departamento",
          nodename=~"$nodename",
          mountpoint="/"
        }
        /
        node_filesystem_size_bytes{
          departamento=~"$departamento",
          nodename=~"$nodename",
          mountpoint="/"
        }
      )
    )
  ),
  "metric", "Disco %", "nodename", ".*"
)

label_replace(
  100 *
  node_load1{
    departamento=~"$departamento",
    nodename=~"$nodename"
  }
  /
  on(departamento, nodename)
  count by(departamento, nodename) (
    node_cpu_seconds_total{
      mode="idle",
      departamento=~"$departamento",
      nodename=~"$nodename"
    }
  ),
  "metric", "Load %", "nodename", ".*"
)

label_replace(
  max by (departamento, nodename) (
    (
      time()
      -
      node_boot_time_seconds{
        departamento=~"$departamento",
        nodename=~"$nodename"
      }
    ) / 86400
  ),
  "metric", "Uptime", "nodename", ".*"
)

up{
  departamento=~"$departamento",
  nodename=~"$nodename"
}

count(
  up{
    departamento=~"$departamento",
    nodename=~"$nodename"
  }
)

avg(
  100 -
  (
    avg by (instance, nodename) (
      rate(
        node_cpu_seconds_total{
          mode="idle",
          departamento=~"$departamento",
          nodename=~"$nodename"
        }[5m]
      )
    ) * 100
  )
)

avg(
  (
    1 -
    (
      node_memory_MemAvailable_bytes{
        departamento=~"$departamento",
        nodename=~"$nodename"
      }
      /
      node_memory_MemTotal_bytes{
        departamento=~"$departamento",
        nodename=~"$nodename"
      }
    )
  ) * 100
)

100 - (
  avg by (job, nodename) (
    rate(
      node_cpu_seconds_total{
        mode="idle",
        departamento=~"$departamento",
        nodename=~"$nodename"
      }[5m]
    )
  ) * 100
)

(
  1 -
  (
    node_memory_MemAvailable_bytes{
      departamento=~"$departamento",
      nodename=~"$nodename"
    }
    /
    node_memory_MemTotal_bytes{
      departamento=~"$departamento",
      nodename=~"$nodename"
    }
  )
) * 100

100 * (
  1 -
  (
    node_filesystem_avail_bytes{
      departamento=~"$departamento",
      nodename=~"$nodename",
      fstype!~"tmpfs|overlay|squashfs|ramfs|rootfs",
      mountpoint!~"/run.*|/snap.*|/var/lib/docker.*"
    }
    /
    node_filesystem_size_bytes{
      departamento=~"$departamento",
      nodename=~"$nodename",
      fstype!~"tmpfs|overlay|squashfs|ramfs|rootfs",
      mountpoint!~"/run.*|/snap.*|/var/lib/docker.*"
    }
  )
)

node_filesystem_avail_bytes{
  departamento=~"$departamento",
  nodename=~"$nodename",
  fstype!~"tmpfs|overlay|squashfs|ramfs|rootfs",
  mountpoint!~"/run.*|/snap.*|/var/lib/docker.*"
}
